),

manifest as (
    {{ bronze_manifest() }}
),

typed as (
    select
        {{ to_type('raw."send_id"', 'varchar') }} as "send_id",
        {{ to_type('raw."send_date"', 'timestamp') }} as "send_date",
        raw."send_date" as __raw_send_date,
        {{ to_type('raw."process_date"', 'date') }} as "process_date",
